/**
 * Minimal reader for the TIFF flavour an ArcGIS ImageServer export produces
 * with `format=tiff&pixelType=F32`: single-band, uncompressed, float32 (or
 * int16/int32/uint16/float64), in strips or in tiles (USGS 3DEP exports
 * 128 px tiles). No library and no compression; anything else throws so the
 * failure is visible.
 */

const TAG = {
  width: 256,
  height: 257,
  bitsPerSample: 258,
  compression: 259,
  stripOffsets: 273,
  samplesPerPixel: 277,
  rowsPerStrip: 278,
  stripByteCounts: 279,
  tileWidth: 322,
  tileLength: 323,
  tileOffsets: 324,
  tileByteCounts: 325,
  sampleFormat: 339,
  gdalNoData: 42113,
} as const;

const TYPE_SIZE: Record<number, number> = { 1: 1, 2: 1, 3: 2, 4: 4, 5: 8, 6: 1, 7: 1, 8: 2, 9: 4, 10: 8, 11: 4, 12: 8, 16: 8 };

interface Entry {
  type: number;
  count: number;
  valueOffset: number;
}

export interface FloatTiff {
  width: number;
  height: number;
  /** Elevations, NaN where the file marks no-data. */
  data: Float32Array;
}

export function decodeFloatTiff(buffer: ArrayBuffer, nodataHint: number | null = null): FloatTiff {
  const dv = new DataView(buffer);
  const magic = String.fromCharCode(dv.getUint8(0), dv.getUint8(1));
  const le = magic === 'II';
  if (magic !== 'II' && magic !== 'MM') throw new Error('tiff: bad byte-order mark');
  if (dv.getUint16(2, le) !== 42) throw new Error('tiff: not a classic TIFF');
  const ifd = dv.getUint32(4, le);
  const n = dv.getUint16(ifd, le);
  const entries = new Map<number, Entry>();
  for (let i = 0; i < n; i++) {
    const o = ifd + 2 + i * 12;
    entries.set(dv.getUint16(o, le), { type: dv.getUint16(o + 2, le), count: dv.getUint32(o + 4, le), valueOffset: o + 8 });
  }
  const values = (tag: number): number[] | null => {
    const e = entries.get(tag);
    if (!e) return null;
    const size = TYPE_SIZE[e.type] ?? 1;
    const total = size * e.count;
    const base = total <= 4 ? e.valueOffset : dv.getUint32(e.valueOffset, le);
    const out: number[] = [];
    for (let i = 0; i < e.count; i++) {
      const p = base + i * size;
      switch (e.type) {
        case 3: out.push(dv.getUint16(p, le)); break;
        case 4: out.push(dv.getUint32(p, le)); break;
        case 8: out.push(dv.getInt16(p, le)); break;
        case 9: out.push(dv.getInt32(p, le)); break;
        case 11: out.push(dv.getFloat32(p, le)); break;
        case 12: out.push(dv.getFloat64(p, le)); break;
        default: out.push(dv.getUint8(p)); break;
      }
    }
    return out;
  };
  const ascii = (tag: number): string | null => {
    const e = entries.get(tag);
    if (!e) return null;
    const base = e.count <= 4 ? e.valueOffset : dv.getUint32(e.valueOffset, le);
    let s = '';
    for (let i = 0; i < e.count; i++) {
      const c = dv.getUint8(base + i);
      if (c === 0) break;
      s += String.fromCharCode(c);
    }
    return s;
  };

  const width = values(TAG.width)?.[0];
  const height = values(TAG.height)?.[0];
  if (!width || !height) throw new Error('tiff: missing dimensions');
  const compression = values(TAG.compression)?.[0] ?? 1;
  if (compression !== 1) throw new Error(`tiff: compression ${compression} not supported (uncompressed only)`);
  const spp = values(TAG.samplesPerPixel)?.[0] ?? 1;
  if (spp !== 1) throw new Error(`tiff: ${spp} samples per pixel, expected 1`);
  const bits = values(TAG.bitsPerSample)?.[0] ?? 32;
  const format = values(TAG.sampleFormat)?.[0] ?? 1; // 1 uint, 2 int, 3 float
  const nodataText = ascii(TAG.gdalNoData);
  const nodata = nodataText !== null ? parseFloat(nodataText) : nodataHint;
  const bytesPer = bits / 8;
  const sample = (p: number): number => {
    let v: number;
    if (format === 3) v = bits === 64 ? dv.getFloat64(p, le) : dv.getFloat32(p, le);
    else if (format === 2) v = bits === 16 ? dv.getInt16(p, le) : dv.getInt32(p, le);
    else v = bits === 16 ? dv.getUint16(p, le) : bits === 8 ? dv.getUint8(p) : dv.getUint32(p, le);
    return nodata !== null && (v === nodata || Math.fround(v) === Math.fround(nodata)) ? NaN : v;
  };
  const data = new Float32Array(width * height);

  const tileOffsets = values(TAG.tileOffsets);
  if (tileOffsets) {
    const tw = values(TAG.tileWidth)?.[0];
    const th = values(TAG.tileLength)?.[0];
    if (!tw || !th) throw new Error('tiff: tiled without tile size');
    const across = Math.ceil(width / tw);
    for (let t = 0; t < tileOffsets.length; t++) {
      const tx = (t % across) * tw;
      const ty = Math.floor(t / across) * th;
      for (let r = 0; r < th && ty + r < height; r++) {
        for (let c = 0; c < tw && tx + c < width; c++) {
          data[(ty + r) * width + tx + c] = sample(tileOffsets[t] + (r * tw + c) * bytesPer);
        }
      }
    }
    return { width, height, data };
  }

  const offsets = values(TAG.stripOffsets);
  const counts = values(TAG.stripByteCounts);
  if (!offsets || !counts) throw new Error('tiff: neither strips nor tiles');
  let px = 0;
  for (let s = 0; s < offsets.length; s++) {
    const cnt = Math.floor(counts[s] / bytesPer);
    for (let i = 0; i < cnt && px < data.length; i++, px++) data[px] = sample(offsets[s] + i * bytesPer);
  }
  return { width, height, data };
}
