/**
 * The tile pipeline with its caches and sources. Runs inside the worker by
 * default, or on the main thread as a fallback -- the code is the same, the
 * only environment-specific pieces are the canvas used to decode and encode
 * PNGs, and those are chosen at runtime.
 */
import { PMTiles } from 'pmtiles';
import { Lru } from './lru';
import { decodeFloatTiff } from './tiff';
import { parseTileUrl } from './params';
import { buildPadded, buildRamps, decodeElevations, encodeTerrainRgb, shade, TILE, type Ramps } from './shade';
import type { DemShadeStats, DemSourceInfo, DemSourceSpec, RampOptions } from './types';

export interface PipelineOptions {
  ramps?: RampOptions;
  elevationCacheSize?: number;
  tileCacheSize?: number;
  /**
   * `'bitmap'` (default where createImageBitmap exists): hand MapLibre an
   * ImageBitmap, skipping the PNG encode here and the decode there.
   * `'png'`: return PNG bytes, for callers that need a file.
   */
  output?: 'bitmap' | 'png';
}

export type TileOutput = ImageBitmap | ArrayBuffer;

/** Sentinel for "the source has no tile here": cached so a footprint edge does not re-walk the directory. */
const EMPTY = Symbol('empty');

// A 1x1 transparent PNG. MapLibre's image request never settles for a
// protocol response whose data is null (the tile sits in "loading" for
// ever and its coarser parent keeps being drawn in its place), so an empty
// SHADE tile is answered with a real transparent image. The terrain
// passthrough keeps null: a raster-dem tile must be full size or nothing.
const TRANSPARENT_PNG = Uint8Array.from([
  0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, 0x00, 0x00, 0x00, 0x0d, 0x49, 0x48, 0x44, 0x52, 0x00, 0x00, 0x00, 0x01,
  0x00, 0x00, 0x00, 0x01, 0x08, 0x06, 0x00, 0x00, 0x00, 0x1f, 0x15, 0xc4, 0x89, 0x00, 0x00, 0x00, 0x0b, 0x49, 0x44, 0x41,
  0x54, 0x78, 0x9c, 0x63, 0x60, 0x00, 0x02, 0x00, 0x00, 0x05, 0x00, 0x01, 0xe2, 0x26, 0x05, 0x9b, 0x00, 0x00, 0x00, 0x00,
  0x49, 0x45, 0x4e, 0x44, 0xae, 0x42, 0x60, 0x82,
]);

export class AbortedError extends Error {
  readonly name = 'AbortError';
  constructor() {
    super('demshade tile aborted');
  }
}

interface Source {
  info: DemSourceInfo;
  spec: DemSourceSpec;
  pm?: PMTiles;
  alphaNoData: boolean;
}

const HALF_WORLD = 20037508.342789244;
/** The no-data value we ask the image server to write; a real DEM never holds it. */
const IMAGE_SERVER_NODATA = -999999;

/** exportImage request for one web-mercator tile as a float32 TIFF, no-data preserved. */
export function imageServerTileUrl(base: string, z: number, x: number, y: number): string {
  const span = (2 * HALF_WORLD) / 2 ** z;
  const minX = -HALF_WORLD + x * span;
  const maxY = HALF_WORLD - y * span;
  const bbox = `${minX},${maxY - span},${minX + span},${maxY}`;
  const q =
    `bbox=${bbox}&bboxSR=3857&imageSR=3857&size=${TILE},${TILE}&format=tiff&pixelType=F32` +
    `&noData=${IMAGE_SERVER_NODATA}&noDataInterpretation=esriNoDataMatchAny&interpolation=RSP_BilinearInterpolation&f=image`;
  return `${base.replace(/\/+$/, '')}/exportImage?${q}`;
}

export class Pipeline {
  private readonly sources = new Map<string, Source>();
  // addSource is async (a PMTiles header read); a tile request that arrives
  // while it is pending waits for it instead of failing as "unknown source",
  // so callers may register a source and add the layer in the same tick.
  private readonly pendingSources = new Map<string, Promise<unknown>>();
  // Two caches, because there are two distinct costs to avoid.
  //
  //  elevCache  decoded elevations, keyed by tile. Survives changes to the
  //             shading options, so dragging a slider is pure recompute with
  //             no network and no PNG decode. Holds the in-flight PROMISE:
  //             a 4x4 block of tiles asks for 144 neighbours covering only
  //             36 distinct tiles, and they all start together -- caching the
  //             resolved value would let every one of those miss.
  //  tileCache  finished PNG bytes, keyed by the full request URL (source +
  //             tile + every shading parameter). Flipping between two DEMs
  //             over the same ground becomes a Map lookup, not a re-render.
  private readonly elevCache: Lru<Promise<Float32Array | null>>;
  // Finished tiles are cached as raw RGBA (256 KB each) rather than PNG: a
  // hit then costs one createImageBitmap, not a PNG decode.
  private readonly tileCache: Lru<Uint8ClampedArray<ArrayBuffer> | typeof EMPTY>;
  private readonly output: 'bitmap' | 'png';
  private ramps: Ramps;
  private readonly stats = { elevHit: 0, elevMiss: 0, tileHit: 0, tileMiss: 0 };

  constructor(o: PipelineOptions = {}) {
    this.ramps = buildRamps(o.ramps);
    this.elevCache = new Lru(o.elevationCacheSize ?? 220);
    this.tileCache = new Lru(o.tileCacheSize ?? 200);
    this.output = o.output ?? (typeof createImageBitmap === 'function' ? 'bitmap' : 'png');
  }

  setRamps(ramps: RampOptions): void {
    this.ramps = buildRamps(ramps);
    this.tileCache.clear();
  }

  addSource(id: string, spec: DemSourceSpec): Promise<DemSourceInfo> {
    const job = this.addSourceNow(id, spec);
    this.pendingSources.set(id, job);
    job.finally(() => this.pendingSources.delete(id)).catch(() => undefined);
    return job;
  }

  private async addSourceNow(id: string, spec: DemSourceSpec): Promise<DemSourceInfo> {
    if (!spec.pmtiles && !spec.tiles && !spec.imageServer) {
      throw new Error('demshade source needs `pmtiles`, `tiles` or `imageServer`');
    }
    if (spec.fill && !this.sources.has(spec.fill) && !this.pendingSources.has(spec.fill)) {
      throw new Error(`demshade: fill source "${spec.fill}" is not registered`);
    }
    if (spec.tileSize && spec.tileSize !== TILE) throw new Error('demshade supports 256 px DEM tiles only');
    const info: DemSourceInfo = {
      id,
      encoding: spec.encoding ?? 'mapbox',
      minzoom: spec.minzoom ?? 0,
      maxzoom: spec.maxzoom ?? (spec.imageServer ? 18 : 15),
      bounds: spec.bounds,
      fill: spec.fill,
    };
    const src: Source = { info, spec, alphaNoData: spec.alphaNoData !== false };
    if (spec.pmtiles) {
      src.pm = new PMTiles(spec.pmtiles);
      const h = await src.pm.getHeader();
      if (spec.minzoom === undefined) info.minzoom = h.minZoom;
      if (spec.maxzoom === undefined) info.maxzoom = h.maxZoom;
      // Archives written without bounds carry the whole-world default; that
      // is "unknown", not a footprint, so leave bounds unset in that case.
      const world = h.minLon <= -180 && h.maxLon >= 180 && h.minLat <= -85 && h.maxLat >= 85;
      if (!spec.bounds && !world && h.minLon < h.maxLon && h.minLat < h.maxLat) {
        info.bounds = [h.minLon, h.minLat, h.maxLon, h.maxLat];
      }
    }
    this.sources.set(id, src);
    return { ...info };
  }

  removeSource(id: string): void {
    this.sources.delete(id);
    // Cached tiles for it would just sit there until evicted; drop them now.
    this.tileCache.clear();
  }

  hasSource(id: string): boolean {
    return this.sources.has(id);
  }

  getStats(): DemShadeStats {
    return { ...this.stats, elevCached: this.elevCache.size, tilesCached: this.tileCache.size };
  }

  clear(): void {
    this.elevCache.clear();
    this.tileCache.clear();
  }

  /** Render one tile. Resolves with an ImageBitmap (or PNG bytes, see `output`), or null where the source is empty. */
  async render(url: string, signal?: AbortSignal): Promise<TileOutput | null> {
    const req = parseTileUrl(url);
    if (!req) throw new Error(`invalid demshade tile url: ${url}`);
    const cached = this.tileCache.get(url);
    if (cached !== undefined) {
      this.stats.tileHit++;
      return cached === EMPTY ? this.empty(req.dem) : this.emit(cached);
    }
    this.stats.tileMiss++;
    let src = this.sources.get(req.sourceId);
    if (!src && this.pendingSources.has(req.sourceId)) {
      await this.pendingSources.get(req.sourceId)!.catch(() => undefined);
      src = this.sources.get(req.sourceId);
    }
    if (!src) throw new Error(`demshade: unknown source "${req.sourceId}"`);

    if (req.dem) {
      // Terrain passthrough: the tile's own elevations, re-encoded so one
      // raster-dem source spec works for every input encoding, and the
      // no-data holes filled so terrain has no pits.
      const elev = await this.elevations(src, req.z, req.x, req.y);
      if (signal?.aborted) throw new AbortedError();
      if (!elev) {
        this.tileCache.set(url, EMPTY);
        return null;
      }
      const px = encodeTerrainRgb(elev);
      this.tileCache.set(url, px);
      return this.emit(px);
    }

    const jobs: Promise<Float32Array | null>[] = [];
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) jobs.push(this.elevations(src, req.z, req.x + dx, req.y + dy));
    }
    const tiles = await Promise.all(jobs);
    // The shared fetches above are never cancelled -- a neighbour may still
    // need them. What a cancelled tile skips is the work only it would use.
    if (signal?.aborted) throw new AbortedError();
    const E = buildPadded(tiles);
    if (!E) {
      this.tileCache.set(url, EMPTY);
      return this.empty(false);
    }
    const px = shade(E, req.z, req.y, req.params, this.ramps);
    if (signal?.aborted) throw new AbortedError();
    this.tileCache.set(url, px);
    return this.emit(px);
  }

  /** What an empty tile is delivered as: null for terrain, a transparent image for shading. */
  private empty(dem: boolean): Promise<TileOutput | null> {
    if (dem) return Promise.resolve(null);
    if (this.output === 'bitmap') {
      return createImageBitmap(new ImageData(new Uint8ClampedArray(4), 1, 1));
    }
    return Promise.resolve(TRANSPARENT_PNG.slice().buffer);
  }

  /** RGBA -> what the caller gets. Always a fresh object: bitmaps are consumed and buffers may be transferred. */
  private emit(px: Uint8ClampedArray<ArrayBuffer>): Promise<TileOutput> {
    if (this.output === 'bitmap') return createImageBitmap(new ImageData(px, TILE, TILE));
    return encodePng(px);
  }

  // ---- elevations -----------------------------------------------------------
  private elevations(src: Source, z: number, x: number, y: number): Promise<Float32Array | null> {
    const n = 1 << z;
    if (y < 0 || y >= n) return Promise.resolve(null);
    x = ((x % n) + n) % n; // wrap the antimeridian
    const key = `${src.info.id}/${z}/${x}/${y}`;
    const hit = this.elevCache.get(key);
    if (hit !== undefined) {
      this.stats.elevHit++;
      return hit;
    }
    this.stats.elevMiss++;
    const once = async (): Promise<Float32Array | null> => {
      const own = await this.decodeOwn(src, z, x, y);
      if (!src.info.fill) return own;
      // Composite: this source where it has a value, the fill elsewhere.
      const fillSrc = this.sources.get(src.info.fill);
      if (!fillSrc) return own;
      const fill = await this.elevations(fillSrc, z, x, y);
      if (!own) return fill;
      if (!fill) return own;
      const out = new Float32Array(own.length);
      for (let i = 0; i < own.length; i++) {
        const v = own[i];
        out[i] = v === v ? v : fill[i];
      }
      return out;
    };
    // One retry absorbs the single dropped request a jittery link produces.
    // Anything worse REJECTS: MapLibre then marks the tile errored and asks
    // again on the next view change. Turning a failure into null here would
    // cache a network hiccup as a permanent blank for the whole session.
    const job = once().catch(() => new Promise((r) => setTimeout(r, 400)).then(once));
    job.catch(() => this.elevCache.delete(key));
    this.elevCache.set(key, job);
    return job;
  }

  /** This source's own elevations for a tile, or null where it has no tile. */
  private async decodeOwn(src: Source, z: number, x: number, y: number): Promise<Float32Array | null> {
    const bytes = await this.fetchTile(src, z, x, y);
    if (!bytes) return null;
    if (src.spec.imageServer) {
      const t = decodeFloatTiff(bytes, IMAGE_SERVER_NODATA);
      if (t.width !== TILE || t.height !== TILE) throw new Error(`demshade: image server returned ${t.width}x${t.height}`);
      // An export that is entirely no-data is "no tile here".
      let any = false;
      for (let i = 0; i < t.data.length; i++) if (t.data[i] === t.data[i]) { any = true; break; }
      return any ? t.data : null;
    }
    const rgba = await decodePng(bytes);
    return decodeElevations(rgba, src.info.encoding, src.alphaNoData);
  }

  /** Raw tile bytes, or null where the source has no tile (outside its footprint / zoom range). */
  private async fetchTile(src: Source, z: number, x: number, y: number): Promise<ArrayBuffer | null> {
    if (z < src.info.minzoom || z > src.info.maxzoom) return null;
    if (src.spec.imageServer) {
      const r = await fetch(imageServerTileUrl(src.spec.imageServer, z, x, y));
      if (!r.ok) throw new Error(`demshade: ${r.status} from image server`);
      const ct = r.headers.get('content-type') || '';
      if (ct.includes('json')) throw new Error('demshade: image server returned an error document');
      return r.arrayBuffer();
    }
    if (src.pm) {
      const t = await src.pm.getZxy(z, x, y);
      return t ? t.data : null;
    }
    const url = (src.spec.tiles as string)
      .replace('{z}', String(z))
      .replace('{x}', String(x))
      .replace('{y}', String(y));
    const r = await fetch(url);
    if (r.status === 404 || r.status === 204) return null;
    if (!r.ok) throw new Error(`demshade: ${r.status} fetching ${url}`);
    return r.arrayBuffer();
  }
}

// ---- canvas helpers ---------------------------------------------------------
// OffscreenCanvas exists in workers and on the main thread of every current
// browser; the element path only serves very old main-thread fallbacks.

type Canvas2D = OffscreenCanvasRenderingContext2D | CanvasRenderingContext2D;

function canvas(): { ctx: Canvas2D; toPng: () => Promise<ArrayBuffer> } {
  if (typeof OffscreenCanvas !== 'undefined') {
    const c = new OffscreenCanvas(TILE, TILE);
    const ctx = c.getContext('2d', { willReadFrequently: true }) as OffscreenCanvasRenderingContext2D | null;
    if (!ctx) throw new Error('demshade: no 2d context');
    return { ctx, toPng: () => c.convertToBlob({ type: 'image/png' }).then((b) => b.arrayBuffer()) };
  }
  if (typeof document === 'undefined') throw new Error('demshade: no canvas available in this environment');
  const c = document.createElement('canvas');
  c.width = c.height = TILE;
  const ctx = c.getContext('2d', { willReadFrequently: true });
  if (!ctx) throw new Error('demshade: no 2d context');
  return {
    ctx,
    toPng: () =>
      new Promise<ArrayBuffer>((resolve, reject) =>
        c.toBlob((b) => (b ? resolve(b.arrayBuffer()) : reject(new Error('demshade: toBlob failed'))), 'image/png'),
      ),
  };
}

export async function decodePng(bytes: ArrayBuffer): Promise<Uint8ClampedArray> {
  const bmp = await createImageBitmap(new Blob([bytes]));
  try {
    if (bmp.width !== TILE || bmp.height !== TILE) {
      throw new Error(`demshade: expected a ${TILE} px tile, got ${bmp.width}x${bmp.height}`);
    }
    const { ctx } = canvas();
    ctx.drawImage(bmp, 0, 0);
    return ctx.getImageData(0, 0, TILE, TILE).data;
  } finally {
    bmp.close?.();
  }
}

export async function encodePng(rgba: Uint8ClampedArray<ArrayBuffer>): Promise<ArrayBuffer> {
  const { ctx, toPng } = canvas();
  ctx.putImageData(new ImageData(rgba, TILE, TILE), 0, 0);
  return toPng();
}
