import type { BlendMode, ShadeOptions, ShadeParams } from './types';

export const BLEND_CODES: Record<BlendMode, number> = { overlay: 0, normal: 1, hardlight: 2, multiply: 3 };
const BLEND_NAMES: BlendMode[] = ['overlay', 'normal', 'hardlight', 'multiply'];

/** Blend code -> name; unknown codes fall back to overlay. */
export function blendName(code: number): BlendMode {
  return BLEND_NAMES[code] ?? 'overlay';
}

/** Defaults, in URL-key form. */
export const DEFAULT_PARAMS: Readonly<ShadeParams> = Object.freeze({
  az: 315,
  alt: 45,
  hs: 1,
  bl: 2, // hard light: the only mode that shows shade on the slope ramp's white band
  sl: 0,
  md: 0,
  as: 0,
  ve: 1,
});

const KEYS = Object.keys(DEFAULT_PARAMS) as (keyof ShadeParams)[];

/** Long option names -> short URL keys. */
export function toParams(o: ShadeOptions = {}): ShadeParams {
  return {
    az: num(o.azimuth, DEFAULT_PARAMS.az),
    alt: num(o.altitude, DEFAULT_PARAMS.alt),
    hs: num(o.hillshade, DEFAULT_PARAMS.hs),
    bl: o.blend && o.blend in BLEND_CODES ? BLEND_CODES[o.blend] : DEFAULT_PARAMS.bl,
    sl: num(o.slope, DEFAULT_PARAMS.sl),
    md: num(o.banding, DEFAULT_PARAMS.md),
    as: num(o.aspect, DEFAULT_PARAMS.as),
    ve: num(o.exaggeration, DEFAULT_PARAMS.ve),
  };
}

/** Short URL keys -> long option names. */
export function toOptions(p: Partial<ShadeParams>): Required<ShadeOptions> {
  const q = { ...DEFAULT_PARAMS, ...p };
  return {
    azimuth: q.az,
    altitude: q.alt,
    hillshade: q.hs,
    blend: blendName(q.bl),
    slope: q.sl,
    banding: q.md,
    aspect: q.as,
    exaggeration: q.ve,
  };
}

function num(v: number | undefined, d: number): number {
  return typeof v === 'number' && Number.isFinite(v) ? v : d;
}

/**
 * Build the tile URL template for a MapLibre raster source. Every shading
 * parameter is in the query string, which is what makes the finished-tile
 * cache key correct and a slider change a new tile set.
 */
export function buildTileUrl(protocol: string, sourceId: string, o: ShadeOptions = {}): string {
  const p = toParams(o);
  const q = KEYS.map((k) => `${k}=${p[k]}`).join('&');
  return `${protocol}://${sourceId}/{z}/{x}/{y}?${q}`;
}

export interface ParsedTileUrl {
  sourceId: string;
  z: number;
  x: number;
  y: number;
  params: ShadeParams;
  /** True for a `dem=1` request: the elevation tile itself, re-encoded as Mapbox terrain-RGB for a raster-dem source. */
  dem: boolean;
}

/** Tile URL template for a MapLibre `raster-dem` source backed by the same DEM. */
export function buildDemTileUrl(protocol: string, sourceId: string): string {
  return `${protocol}://${sourceId}/{z}/{x}/{y}?dem=1`;
}

/** Parse `scheme://<source>/<z>/<x>/<y>?az=..&alt=..`. Returns null if malformed. */
export function parseTileUrl(url: string): ParsedTileUrl | null {
  const m = /^[a-z][a-z0-9+.-]*:\/\/([^/?#]+)\/(\d+)\/(\d+)\/(\d+)(?:\?([^#]*))?$/i.exec(url);
  if (!m) return null;
  const params: ShadeParams = { ...DEFAULT_PARAMS };
  let dem = false;
  if (m[5]) {
    for (const part of m[5].split('&')) {
      const eq = part.indexOf('=');
      if (eq < 0) continue;
      const k = decodeURIComponent(part.slice(0, eq)) as keyof ShadeParams | 'dem';
      if (k === 'dem') {
        dem = part.slice(eq + 1) === '1';
        continue;
      }
      if (!(k in DEFAULT_PARAMS)) continue;
      const v = Number(decodeURIComponent(part.slice(eq + 1)));
      if (Number.isFinite(v)) params[k] = v;
    }
  }
  return {
    sourceId: decodeURIComponent(m[1]),
    z: Number(m[2]),
    x: Number(m[3]),
    y: Number(m[4]),
    params,
    dem,
  };
}
