import { addProtocol, removeProtocol } from 'maplibre-gl';
import type { RequestParameters } from 'maplibre-gl';
import { AbortedError, Pipeline, type TileOutput } from './pipeline';
import { buildDemTileUrl, buildTileUrl } from './params';
import type { FromWorker, ToWorker } from '../worker/protocol';
import type {
  DemShadeOptions,
  DemShadeStats,
  DemSourceInfo,
  DemSourceSpec,
  RampOptions,
  ShadeOptions,
} from './types';
import DemShadeWorker from '../worker/demshade.worker?worker&inline';

type Pending = { resolve: (v: unknown) => void; reject: (e: Error) => void };

/**
 * Registers a MapLibre protocol that turns terrain-RGB / Terrarium DEM tiles
 * into shaded-relief raster tiles, computed in a Web Worker.
 *
 *   const demshade = new DemShade();
 *   const info = await demshade.addSource('homer', { pmtiles: '.../homer_2019.pmtiles' });
 *   map.addSource('shade', demshade.rasterSource('homer', { slope: 0.6 }));
 *   map.addLayer({ id: 'shade', type: 'raster', source: 'shade' });
 */
export class DemShade {
  readonly protocol: string;
  private readonly useWorker: boolean;
  private worker: Worker | null = null;
  private local: Pipeline | null = null;
  private readonly pending = new Map<number, Pending>();
  private readonly sources = new Map<string, DemSourceInfo>();
  private seq = 0;
  private registered = false;
  private ready: Promise<void>;

  constructor(private readonly options: DemShadeOptions = {}) {
    this.protocol = options.protocol ?? 'demshade';
    this.useWorker =
      options.worker !== false &&
      typeof Worker !== 'undefined' &&
      typeof OffscreenCanvas !== 'undefined' &&
      typeof createImageBitmap !== 'undefined';
    this.ready = this.start();
    this.register();
  }

  // ---- lifecycle -------------------------------------------------------------

  private start(): Promise<void> {
    if (!this.useWorker) {
      this.local = new Pipeline(this.options);
      return Promise.resolve();
    }
    try {
      const w: Worker = new DemShadeWorker();
      this.worker = w;
      w.onmessage = (ev: MessageEvent<FromWorker>) => this.onMessage(ev.data);
      w.onerror = () => this.failAll(new Error('demshade worker crashed'));
      return new Promise<void>((resolve) => {
        const onReady = (ev: MessageEvent<FromWorker>) => {
          if (ev.data.type === 'ready') {
            w.removeEventListener('message', onReady);
            resolve();
          }
        };
        w.addEventListener('message', onReady);
        this.send({
          type: 'init',
          ramps: this.options.ramps,
          elevationCacheSize: this.options.elevationCacheSize,
          tileCacheSize: this.options.tileCacheSize,
          output: this.options.output,
        });
      });
    } catch {
      // Worker construction can fail under strict CSPs; the pipeline is the
      // same code, so fall back to running it here.
      this.worker = null;
      this.local = new Pipeline(this.options);
      return Promise.resolve();
    }
  }

  private register(): void {
    if (this.registered) return;
    addProtocol(this.protocol, (params: RequestParameters, abortController: AbortController) =>
      this.loadTile(params.url, abortController.signal).then((data) => ({ data })),
    );
    this.registered = true;
  }

  /** Unregister the protocol and stop the worker. The instance is unusable afterwards. */
  remove(): void {
    if (this.registered) {
      removeProtocol(this.protocol);
      this.registered = false;
    }
    this.worker?.terminate();
    this.worker = null;
    this.local = null;
    this.failAll(new Error('demshade removed'));
  }

  /** True when tiles are rendered off the main thread. */
  get inWorker(): boolean {
    return this.worker !== null;
  }

  // ---- sources ---------------------------------------------------------------

  /** Register a DEM source. Resolves with zoom range and bounds (read from a PMTiles header when available). */
  async addSource(id: string, spec: DemSourceSpec): Promise<DemSourceInfo> {
    await this.ready;
    const info = this.local
      ? await this.local.addSource(id, spec)
      : ((await this.call({ type: 'addSource', req: 0, id, spec })) as DemSourceInfo);
    this.sources.set(id, info);
    return info;
  }

  removeSource(id: string): void {
    this.sources.delete(id);
    if (this.local) this.local.removeSource(id);
    else this.send({ type: 'removeSource', id });
  }

  getSource(id: string): DemSourceInfo | undefined {
    return this.sources.get(id);
  }

  listSources(): DemSourceInfo[] {
    return [...this.sources.values()];
  }

  setRamps(ramps: RampOptions): void {
    if (this.local) this.local.setRamps(ramps);
    else this.send({ type: 'setRamps', ramps });
  }

  // ---- tiles -----------------------------------------------------------------

  /** Tile URL template for a MapLibre raster source. */
  tileUrl(sourceId: string, o: ShadeOptions = {}): string {
    return buildTileUrl(this.protocol, sourceId, o);
  }

  /** A complete MapLibre raster source spec for `map.addSource`. */
  rasterSource(sourceId: string, o: ShadeOptions = {}): {
    type: 'raster';
    tiles: string[];
    tileSize: number;
    minzoom?: number;
    maxzoom?: number;
    bounds?: [number, number, number, number];
  } {
    const info = this.sources.get(sourceId);
    const spec: ReturnType<DemShade['rasterSource']> = {
      type: 'raster',
      tiles: [this.tileUrl(sourceId, o)],
      tileSize: 256,
    };
    if (info) {
      spec.minzoom = info.minzoom;
      spec.maxzoom = info.maxzoom;
      if (info.bounds) spec.bounds = info.bounds;
    }
    return spec;
  }

  /** Tile URL template that returns the DEM itself as Mapbox terrain-RGB, for `raster-dem`. */
  demTileUrl(sourceId: string): string {
    return buildDemTileUrl(this.protocol, sourceId);
  }

  /**
   * A MapLibre `raster-dem` source spec backed by this DEM, for `map.setTerrain`
   * or a hillshade layer. Works for PMTiles archives too, which MapLibre cannot
   * read as terrain by itself.
   */
  rasterDemSource(sourceId: string): {
    type: 'raster-dem';
    tiles: string[];
    tileSize: number;
    encoding: 'mapbox';
    minzoom?: number;
    maxzoom?: number;
    bounds?: [number, number, number, number];
  } {
    const info = this.sources.get(sourceId);
    const spec: ReturnType<DemShade['rasterDemSource']> = {
      type: 'raster-dem',
      tiles: [this.demTileUrl(sourceId)],
      tileSize: 256,
      encoding: 'mapbox',
    };
    if (info) {
      spec.minzoom = info.minzoom;
      spec.maxzoom = info.maxzoom;
      if (info.bounds) spec.bounds = info.bounds;
    }
    return spec;
  }

  /**
   * Render one tile without a map: an ImageBitmap by default, PNG bytes with
   * `output: 'png'`. MapLibre goes through the registered protocol, which
   * calls this.
   */
  async loadTile(url: string, signal?: AbortSignal): Promise<TileOutput | null> {
    if (signal?.aborted) throw new AbortedError();
    await this.ready;
    if (signal?.aborted) throw new AbortedError();
    if (this.local) return this.local.render(url, signal);
    const req = ++this.seq;
    const onAbort = () => this.send({ type: 'abort', req });
    signal?.addEventListener('abort', onAbort, { once: true });
    try {
      return (await this.call({ type: 'tile', req, url }, req)) as TileOutput | null;
    } finally {
      signal?.removeEventListener('abort', onAbort);
    }
  }

  async stats(): Promise<DemShadeStats> {
    await this.ready;
    if (this.local) return this.local.getStats();
    return (await this.call({ type: 'stats', req: 0 })) as DemShadeStats;
  }

  clearCache(): void {
    if (this.local) this.local.clear();
    else this.send({ type: 'clear' });
  }

  // ---- worker plumbing -------------------------------------------------------

  private send(m: ToWorker): void {
    this.worker?.postMessage(m);
  }

  private call(m: Extract<ToWorker, { req: number }>, req = ++this.seq): Promise<unknown> {
    if (!this.worker) return Promise.reject(new Error('demshade: worker not running'));
    return new Promise((resolve, reject) => {
      this.pending.set(req, { resolve, reject });
      this.send({ ...m, req });
    });
  }

  private onMessage(m: FromWorker): void {
    if (m.type === 'ready') return;
    const p = this.pending.get(m.req);
    if (!p) return;
    this.pending.delete(m.req);
    switch (m.type) {
      case 'tile':
        p.resolve(m.data);
        break;
      case 'source':
        p.resolve(m.info);
        break;
      case 'stats':
        p.resolve(m.stats);
        break;
      case 'error': {
        const err = new Error(m.message);
        if (m.aborted) err.name = 'AbortError';
        p.reject(err);
        break;
      }
    }
  }

  private failAll(err: Error): void {
    for (const p of this.pending.values()) p.reject(err);
    this.pending.clear();
  }
}
