import type { IControl, Map as MapLibreMap } from 'maplibre-gl';
import type { DemShade } from './DemShade';
import type { BlendMode, ShadeOptions } from './types';
import { trackTerrainCenter } from './terrain-center';

export interface DemShadeControlOptions {
  /** The DemShade instance whose sources the control offers. */
  demshade: DemShade;
  /** Source id to show first. Default: the first registered source. */
  source?: string;
  /** Initial shading. */
  shade?: ShadeOptions;
  /** Initial layer opacity 0..1. Default 1. */
  opacity?: number;
  /** MapLibre layer id to insert the shading layer before. Default: on top. */
  beforeId?: string;
  /** Panel title. Default 'Shaded relief'. */
  title?: string;
  /** Start with the panel folded to its title bar. Default false. */
  collapsed?: boolean;
  /** Id prefix for the MapLibre source and layer this control manages. Default 'demshade'. */
  layerId?: string;
  /** Start with 3D terrain on. Default false. */
  terrain?: boolean;
  /** Terrain exaggeration for `map.setTerrain`. Default 1.5. */
  terrainExaggeration?: number;
  /** Offer the 3D terrain toggle. Default true. */
  showTerrain?: boolean;
}

export interface DemShadeControlState {
  source: string | null;
  shade: Required<ShadeOptions>;
  opacity: number;
  visible: boolean;
  /** 3D terrain from the same DEM, via `map.setTerrain`. */
  terrain: boolean;
  terrainExaggeration: number;
}

type Listener = (state: DemShadeControlState) => void;

const BLENDS: [BlendMode, string][] = [
  ['hardlight', 'Hard light (shade decides)'],
  ['overlay', 'Overlay (QGIS; fades on pale ramps)'],
  ['multiply', 'Multiply (shadows only)'],
  ['normal', 'Plain transparency'],
];

const SLIDERS: { key: keyof ShadeOptions; label: string; min: number; max: number; step: number; scale?: number }[] = [
  // Top to bottom, like a layer list: each ramp's slider is its opacity
  // over what is beneath it.
  { key: 'hillshade', label: 'Hillshade', min: 0, max: 1, step: 0.05 },
  { key: 'slope', label: 'Slope ramp', min: 0, max: 1, step: 0.05 },
  { key: 'banding', label: 'Elevation bands', min: 0, max: 1, step: 0.05 },
  { key: 'aspect', label: 'Aspect tint', min: 0, max: 1, step: 0.05 },
  { key: 'azimuth', label: 'Sun azimuth', min: 0, max: 360, step: 1 },
  { key: 'altitude', label: 'Sun altitude', min: 0, max: 90, step: 1 },
  { key: 'exaggeration', label: 'Shade exagg.', min: 0.2, max: 5, step: 0.1 },
];

/**
 * A small MapLibre control: pick a DEM source and drag the shading sliders.
 * Manages one raster source + layer on the map; every slider change swaps the
 * tile URL, and the worker's caches make that a recompute, not a refetch.
 */
export class DemShadeControl implements IControl {
  private map: MapLibreMap | null = null;
  private container: HTMLElement | null = null;
  private readonly listeners = new Set<Listener>();
  private readonly layerId: string;
  private state: DemShadeControlState;
  private inputs = new Map<string, HTMLInputElement>();
  private select: HTMLSelectElement | null = null;
  private blendSelect: HTMLSelectElement | null = null;
  // MapLibre's isStyleLoaded() is false whenever any source still has tiles
  // in flight, which with a raster overlay is most of the time. Gate on the
  // style having loaded once instead, or a checkbox change that lands
  // mid-stream is silently dropped.
  private styleReady = false;
  private untrack: (() => void) | null = null;

  constructor(private readonly options: DemShadeControlOptions) {
    this.layerId = options.layerId ?? 'demshade';
    this.state = {
      source: options.source ?? options.demshade.listSources()[0]?.id ?? null,
      shade: fill(options.shade),
      opacity: options.opacity ?? 1,
      visible: true,
      terrain: options.terrain ?? false,
      terrainExaggeration: options.terrainExaggeration ?? 1.5,
    };
  }

  onAdd(map: MapLibreMap): HTMLElement {
    this.map = map;
    this.container = this.render();
    if (map.isStyleLoaded()) {
      this.styleReady = true;
      this.sync();
    } else {
      map.once('load', () => {
        this.styleReady = true;
        this.sync();
      });
    }
    map.on('style.load', this.onStyleLoad);
    map.on('styledata', this.onStyle);
    return this.container;
  }

  onRemove(): void {
    this.map?.off('style.load', this.onStyleLoad);
    this.map?.off('styledata', this.onStyle);
    this.setTerrain(false);
    this.removeLayer();
    this.container?.remove();
    this.container = null;
    this.map = null;
  }

  getState(): DemShadeControlState {
    return { ...this.state, shade: { ...this.state.shade } };
  }

  setState(next: Partial<DemShadeControlState>): void {
    this.state = {
      ...this.state,
      ...next,
      shade: next.shade ? { ...this.state.shade, ...next.shade } : this.state.shade,
    };
    this.refreshInputs();
    this.sync();
    this.emit();
  }

  on(listener: Listener): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  /** Re-read the DemShade source list (call after addSource). */
  refreshSources(): void {
    if (!this.select) return;
    const sources = this.options.demshade.listSources();
    this.select.innerHTML = '';
    for (const s of sources) {
      const opt = document.createElement('option');
      opt.value = s.id;
      opt.textContent = s.id;
      this.select.appendChild(opt);
    }
    if (!this.state.source && sources[0]) this.state.source = sources[0].id;
    if (this.state.source) this.select.value = this.state.source;
    this.sync();
  }

  // ---- map ---------------------------------------------------------------------

  private onStyleLoad = (): void => {
    // A style swap drops our source, layer and terrain; put them back.
    this.styleReady = true;
    this.sync();
  };

  private onStyle = (): void => {
    if (this.map && this.styleReady && !this.map.getSource(this.layerId)) this.sync();
  };

  private sync(): void {
    const map = this.map;
    if (!map || !this.styleReady) return;
    const { source, shade, opacity, visible } = this.state;
    if (!source || !this.options.demshade.getSource(source)) {
      this.setTerrain(false);
      this.removeLayer();
      return;
    }
    this.setTerrain(this.state.terrain);
    const spec = this.options.demshade.rasterSource(source, shade);
    const existing = map.getSource(this.layerId) as { setTiles?: (t: string[]) => void } | undefined;
    if (existing && existing.setTiles && (map.getSource(this.layerId) as { minzoom?: number }).minzoom === spec.minzoom) {
      existing.setTiles(spec.tiles);
    } else {
      this.removeLayer();
      map.addSource(this.layerId, spec);
      map.addLayer(
        {
          id: this.layerId,
          type: 'raster',
          source: this.layerId,
          paint: {
            'raster-opacity': opacity,
            // Zero both, or switching between two DEMs cross-fades through
            // the basemap: the outgoing layer fades down before the incoming
            // fades up.
            'raster-fade-duration': 0,
            'raster-opacity-transition': { duration: 0, delay: 0 },
          },
        },
        this.options.beforeId,
      );
    }
    map.setPaintProperty(this.layerId, 'raster-opacity', opacity);
    map.setLayoutProperty(this.layerId, 'visibility', visible ? 'visible' : 'none');
  }

  private removeLayer(): void {
    const map = this.map;
    if (!map) return;
    if (map.getLayer(this.layerId)) map.removeLayer(this.layerId);
    if (map.getSource(this.layerId)) map.removeSource(this.layerId);
  }

  /**
   * 3D terrain from the same DEM through the protocol's `dem=1` passthrough,
   * so it works for PMTiles archives MapLibre could not otherwise read.
   */
  private setTerrain(on: boolean): void {
    const map = this.map;
    if (!map) return;
    const demId = this.layerId + '-dem';
    const { source, terrainExaggeration } = this.state;
    const current = map.getTerrain();
    if (!on || !source) {
      if (current && current.source === demId) {
        map.setTerrain(null);
        this.untrack?.();
        this.untrack = null;
      }
      if (map.getSource(demId) && !(current && current.source === demId && on)) map.removeSource(demId);
      return;
    }
    const spec = this.options.demshade.rasterDemSource(source);
    const existing = map.getSource(demId) as { tiles?: string[]; setTiles?: (t: string[]) => void } | undefined;
    if (existing && existing.tiles && existing.tiles[0] !== spec.tiles[0]) {
      // DEM changed under a live terrain: swap the tiles in place.
      if (existing.setTiles) existing.setTiles(spec.tiles);
      else {
        map.setTerrain(null);
        map.removeSource(demId);
        map.addSource(demId, spec);
      }
    } else if (!existing) {
      map.addSource(demId, spec);
    }
    if (!current || current.source !== demId || current.exaggeration !== terrainExaggeration) {
      map.setTerrain({ source: demId, exaggeration: terrainExaggeration });
    }
    // Sample the centre elevation at quiet moments instead of every frame:
    // see terrain-center.ts for why neither MapLibre default is right.
    if (!this.untrack) this.untrack = trackTerrainCenter(map);
  }

  // ---- DOM ---------------------------------------------------------------------

  private render(): HTMLElement {
    const root = el('div', 'maplibregl-ctrl maplibregl-ctrl-group mgl-demshade');
    const head = el('button', 'mgl-demshade-head');
    head.type = 'button';
    head.textContent = this.options.title ?? 'Shaded relief';
    head.setAttribute('aria-expanded', String(!this.options.collapsed));
    const body = el('div', 'mgl-demshade-body');
    if (this.options.collapsed) body.hidden = true;
    head.addEventListener('click', () => {
      body.hidden = !body.hidden;
      head.setAttribute('aria-expanded', String(!body.hidden));
    });
    root.append(head, body);

    // source picker
    const srcRow = el('label', 'mgl-demshade-row');
    srcRow.append(span('DEM'));
    this.select = document.createElement('select');
    this.select.addEventListener('change', () => this.setState({ source: this.select!.value }));
    srcRow.append(this.select);
    body.append(srcRow);

    // visibility + opacity
    const visRow = el('label', 'mgl-demshade-row');
    const vis = document.createElement('input');
    vis.type = 'checkbox';
    vis.checked = this.state.visible;
    vis.addEventListener('change', () => this.setState({ visible: vis.checked }));
    visRow.append(vis, span('Show'));
    body.append(visRow);
    body.append(this.slider('opacity', 'Opacity', 0, 1, 0.05, this.state.opacity, (v) => this.setState({ opacity: v })));

    // 3D terrain
    if (this.options.showTerrain !== false) {
      const terrRow = el('label', 'mgl-demshade-row');
      const terr = document.createElement('input');
      terr.type = 'checkbox';
      terr.checked = this.state.terrain;
      terr.addEventListener('change', () => this.setState({ terrain: terr.checked }));
      terrRow.append(terr, span('3D terrain'));
      this.inputs.set('terrain', terr);
      body.append(terrRow);
      body.append(
        this.slider('terrainExaggeration', 'Terrain exagg.', 0.5, 5, 0.1, this.state.terrainExaggeration, (v) =>
          this.setState({ terrainExaggeration: v }),
        ),
      );
    }

    // blend mode
    const blendRow = el('label', 'mgl-demshade-row');
    blendRow.append(span('Blend'));
    const blend = document.createElement('select');
    for (const [value, label] of BLENDS) {
      const opt = document.createElement('option');
      opt.value = value;
      opt.textContent = label;
      blend.appendChild(opt);
    }
    blend.value = this.state.shade.blend;
    blend.addEventListener('change', () =>
      this.setState({ shade: { ...this.state.shade, blend: blend.value as BlendMode } }),
    );
    blendRow.append(blend);
    this.blendSelect = blend;
    body.append(blendRow);

    for (const s of SLIDERS) {
      body.append(
        this.slider(s.key, s.label, s.min, s.max, s.step, this.state.shade[s.key] as number, (v) =>
          this.setState({ shade: { ...this.state.shade, [s.key]: v } }),
        ),
      );
    }
    this.refreshSources();
    return root;
  }

  private slider(
    key: string,
    label: string,
    min: number,
    max: number,
    step: number,
    value: number,
    onChange: (v: number) => void,
  ): HTMLElement {
    const row = el('label', 'mgl-demshade-row mgl-demshade-slider');
    const val = span(fmt(value), 'mgl-demshade-val');
    const input = document.createElement('input');
    input.type = 'range';
    input.min = String(min);
    input.max = String(max);
    input.step = String(step);
    input.value = String(value);
    input.addEventListener('input', () => {
      val.textContent = fmt(+input.value);
      onChange(+input.value);
    });
    this.inputs.set(key, input);
    row.append(span(label), input, val);
    return row;
  }

  private refreshInputs(): void {
    for (const s of SLIDERS) {
      const input = this.inputs.get(s.key);
      if (input) {
        input.value = String(this.state.shade[s.key]);
        const val = input.parentElement?.querySelector('.mgl-demshade-val');
        if (val) val.textContent = fmt(this.state.shade[s.key] as number);
      }
    }
    const op = this.inputs.get('opacity');
    if (op) op.value = String(this.state.opacity);
    const terr = this.inputs.get('terrain');
    if (terr) terr.checked = this.state.terrain;
    const tex = this.inputs.get('terrainExaggeration');
    if (tex) tex.value = String(this.state.terrainExaggeration);
    if (this.blendSelect) this.blendSelect.value = this.state.shade.blend;
    if (this.select && this.state.source) this.select.value = this.state.source;
  }

  private emit(): void {
    const s = this.getState();
    for (const l of this.listeners) l(s);
  }
}

function fill(o: ShadeOptions = {}): Required<ShadeOptions> {
  return {
    azimuth: o.azimuth ?? 315,
    altitude: o.altitude ?? 45,
    hillshade: o.hillshade ?? 1,
    blend: o.blend ?? 'hardlight',
    slope: o.slope ?? 0,
    banding: o.banding ?? 0,
    aspect: o.aspect ?? 0,
    exaggeration: o.exaggeration ?? 1,
  };
}

function el<K extends keyof HTMLElementTagNameMap>(tag: K, cls: string): HTMLElementTagNameMap[K] {
  const e = document.createElement(tag);
  e.className = cls;
  return e;
}

function span(text: string, cls = ''): HTMLSpanElement {
  const s = document.createElement('span');
  s.textContent = text;
  if (cls) s.className = cls;
  return s;
}

function fmt(v: number): string {
  return Number.isInteger(v) ? String(v) : v.toFixed(2).replace(/0+$/, '').replace(/\.$/, '');
}
