import type { Map as MapLibreMap } from 'maplibre-gl';

/**
 * Keep the map's centre elevation on the terrain surface without MapLibre's
 * per-frame re-solve, and without moving the camera.
 *
 * MapLibre's default (`centerClampedToGround: true`) re-samples the terrain
 * under the centre every frame and moves the camera with it, so as sharper
 * DEM tiles stream in the view lurches, worst at low pitch with high
 * exaggeration. Turning clamping off stops that, but then the centre sits at
 * sea level: over high ground the surface is far closer to the camera than
 * the zoom says, tiles are chosen for the wrong distance (detail drops on
 * zoom-in and stays low) and rotation pivots about a point in the air.
 *
 * This samples at quiet moments only (after each gesture, and again once the
 * tiles have settled) and applies the new centre elevation the way MapLibre
 * itself does at the end of a terrain drag: re-solving centre and zoom so the
 * camera position and orientation are unchanged. The bookkeeping moves; the
 * picture does not. That path is internal to MapLibre, so it is feature
 * checked, with an eased centre-elevation change as the fallback.
 */
export function trackTerrainCenter(map: MapLibreMap, options: { duration?: number; threshold?: number } = {}): () => void {
  const duration = options.duration ?? 250;
  const threshold = options.threshold ?? 0.25;
  let busy = false;
  let idlePending = false;

  type Internals = {
    terrain?: unknown;
    _getTransformForUpdate?: () => { elevation: number; recalculateZoomAndCenter: (terrain: unknown) => void };
    _applyUpdatedTransform?: (tr: unknown) => void;
  };
  const m = map as unknown as Internals;
  const hasInternals = (): boolean =>
    typeof m._getTransformForUpdate === 'function' && typeof m._applyUpdatedTransform === 'function';

  const settle = (): void => {
    if (busy || !map.getTerrain()) return;
    const target = map.queryTerrainElevation(map.getCenter());
    if (target === null || target === undefined || !Number.isFinite(target)) return;
    if (Math.abs(target - map.getCenterElevation()) < threshold) return;
    busy = true;
    try {
      if (hasInternals()) {
        // Same pair the handler manager uses when a terrain drag ends:
        // camera stays put, centre/zoom/elevation are re-solved.
        const tr = m._getTransformForUpdate!();
        tr.recalculateZoomAndCenter(m.terrain);
        m._applyUpdatedTransform!(tr);
        map.triggerRepaint();
      } else {
        map.easeTo({ elevation: target, duration, essential: true } as never);
      }
    } finally {
      // The fallback's easeTo fires its own moveend; let it pass as a no-op.
      setTimeout(() => {
        busy = false;
      }, 0);
    }
  };

  const onMoveEnd = (): void => {
    if (busy) return;
    settle();
    if (!idlePending) {
      idlePending = true;
      map.once('idle', () => {
        idlePending = false;
        settle();
      });
    }
  };

  map.setCenterClampedToGround?.(false);
  map.on('moveend', onMoveEnd);
  onMoveEnd();
  return () => {
    map.off('moveend', onMoveEnd);
    map.setCenterClampedToGround?.(true);
  };
}
