/**
 * The pure pixel pipeline: terrain-RGB decode, the one-pixel halo, and the
 * shading itself. No DOM, no network -- everything here runs identically in
 * a Web Worker, on the main thread, and under Node in the tests.
 *
 * WHY NOT MapLibre's built-in `hillshade` layer
 * ---------------------------------------------
 *  - It has no `hillshade-opacity`, so a hillshade can only be faded by
 *    changing `hillshade-exaggeration`, which alters the shading itself
 *    rather than blending it. A plain `raster` layer has real opacity.
 *  - `hillshade-illumination-altitude` is ignored by several of the
 *    `hillshade-method` variants, so a sun-altitude control silently does
 *    nothing.
 *  - It cannot do slope shade, aspect shade, or elevation banding at all.
 *
 * Computing here costs no extra storage: slope, aspect and banding are all
 * derivatives of elevation tiles that are already hosted.
 *
 * TILE SEAMS: a slope needs its neighbours, so each output tile is built from
 * a 258x258 grid -- the tile plus a one-pixel halo lifted off the eight
 * surrounding tiles. Without that, every tile border gets a false ridge.
 * Absent neighbours (survey edge) fall back to edge replication, which yields
 * zero slope there rather than a cliff.
 */
import type { DemEncoding, RampOptions, RampStop, ShadeParams } from './types';

export const TILE = 256;
export const PAD = TILE + 2; // one-pixel halo each side
const EARTH = 40075016.686;

// ---- colour ramps ---------------------------------------------------------
// The defaults reproduce a QGIS layer stack used for landslide mapping:
//
//     hillshade        <- grey, OVERLAY blend
//     slope ramp       <- 60% opacity
//     mod-5 m ramp     <- cyclic, opaque
//
// The banding interval is fixed per instance, not per tile: holding it
// constant is what makes banding comparable between sites.
export const DEFAULT_BAND_INTERVAL = 5;

/** Cyclic BrBG-with-black. First and last stop match so it wraps without a seam. */
export const DEFAULT_BAND_STOPS: RampStop[] = [
  [0.0, 0xa6, 0x61, 0x1a],
  [0.833, 0xdf, 0xc2, 0x7d],
  [1.667, 0xf5, 0xf5, 0xf5],
  [2.5, 0x80, 0xcd, 0xc1],
  [3.333, 0x01, 0x85, 0x71],
  [4.167, 0x00, 0x00, 0x00],
  [5.0, 0xa6, 0x61, 0x1a],
];

/**
 * Slope ramp with two deliberate sensitivities: green->white across 0-10
 * resolves near-horizontal ground (benches, scarp crowns, terraces), and the
 * white->yellow->red->purple run across 32-50 brackets the angle of repose.
 */
export const DEFAULT_SLOPE_STOPS: RampStop[] = [
  [0, 0x00, 0x97, 0x08],
  [10, 0xff, 0xff, 0xff],
  [32, 0xeb, 0xec, 0xe2],
  [40, 0xff, 0xec, 0x00],
  [45, 0xf0, 0x00, 0x00],
  [50, 0xb8, 0x00, 0xff],
  [90, 0x00, 0x00, 0x00],
];

export const LUT_N = 512;

export function buildLut(stops: RampStop[], lo: number, hi: number): Uint8Array {
  const lut = new Uint8Array(LUT_N * 3);
  for (let i = 0; i < LUT_N; i++) {
    const v = lo + ((hi - lo) * i) / (LUT_N - 1);
    let k = 0;
    while (k < stops.length - 2 && v > stops[k + 1][0]) k++;
    const s0 = stops[k];
    const s1 = stops[k + 1];
    let f = s1[0] === s0[0] ? 0 : (v - s0[0]) / (s1[0] - s0[0]);
    f = f < 0 ? 0 : f > 1 ? 1 : f;
    lut[i * 3] = s0[1] + (s1[1] - s0[1]) * f;
    lut[i * 3 + 1] = s0[2] + (s1[2] - s0[2]) * f;
    lut[i * 3 + 2] = s0[3] + (s1[3] - s0[3]) * f;
  }
  return lut;
}

export interface Ramps {
  slopeLut: Uint8Array;
  bandLut: Uint8Array;
  bandInterval: number;
}

export function buildRamps(o: RampOptions = {}): Ramps {
  const bandInterval = o.bandInterval && o.bandInterval > 0 ? o.bandInterval : DEFAULT_BAND_INTERVAL;
  const bandStops = o.band && o.band.length >= 2 ? o.band : scaleStops(DEFAULT_BAND_STOPS, bandInterval / DEFAULT_BAND_INTERVAL);
  return {
    slopeLut: buildLut(o.slope && o.slope.length >= 2 ? o.slope : DEFAULT_SLOPE_STOPS, 0, 90),
    bandLut: buildLut(bandStops, 0, bandInterval),
    bandInterval,
  };
}

function scaleStops(stops: RampStop[], k: number): RampStop[] {
  return k === 1 ? stops : stops.map((s) => [s[0] * k, s[1], s[2], s[3]]);
}

// ---- decode -----------------------------------------------------------------

/**
 * RGBA pixels of a 256x256 DEM tile -> Float32 elevations in metres, NaN
 * where there is no data.
 */
export function decodeElevations(
  rgba: Uint8ClampedArray | Uint8Array,
  encoding: DemEncoding,
  alphaNoData = true,
): Float32Array {
  const out = new Float32Array(TILE * TILE);
  if (encoding === 'terrarium') {
    for (let i = 0, p = 0; i < out.length; i++, p += 4) {
      out[i] =
        alphaNoData && rgba[p + 3] === 0
          ? NaN
          : rgba[p] * 256 + rgba[p + 1] + rgba[p + 2] / 256 - 32768;
    }
  } else {
    for (let i = 0, p = 0; i < out.length; i++, p += 4) {
      out[i] =
        alphaNoData && rgba[p + 3] === 0
          ? NaN
          : -10000 + (rgba[p] * 65536 + rgba[p + 1] * 256 + rgba[p + 2]) * 0.1;
    }
  }
  return out;
}

/**
 * Elevations -> Mapbox terrain-RGB pixels for a MapLibre raster-dem source.
 * MapLibre's DEM decoder has no notion of missing data, so NaN is written as
 * 0 m: the least surprising fill outside a partial survey, and it avoids the
 * -10 km pit that decoding a transparent pixel's zero RGB would produce.
 */
export function encodeTerrainRgb(elev: Float32Array, fill = 0): Uint8ClampedArray<ArrayBuffer> {
  const out = new Uint8ClampedArray(elev.length * 4);
  for (let i = 0, p = 0; i < elev.length; i++, p += 4) {
    const h = elev[i];
    let v = Math.round(((h === h ? h : fill) + 10000) * 10);
    v = v < 0 ? 0 : v > 16777215 ? 16777215 : v;
    out[p] = (v >> 16) & 255;
    out[p + 1] = (v >> 8) & 255;
    out[p + 2] = v & 255;
    out[p + 3] = 255;
  }
  return out;
}

// ---- halo -------------------------------------------------------------------

/**
 * Assemble the 258x258 padded grid from the 3x3 neighbourhood. `tiles` is in
 * row-major order (top-left .. bottom-right), index 4 the centre; null means
 * the source has no tile there. Returns null when the centre is missing.
 */
export function buildPadded(tiles: (Float32Array | null)[]): Float32Array | null {
  const C = tiles[4];
  if (!C) return null;
  const E = new Float32Array(PAD * PAD);
  const get = (ti: number, i: number, j: number): number => {
    const a = tiles[ti];
    return a ? a[i * TILE + j] : NaN;
  };
  // interior
  for (let i = 0; i < TILE; i++) {
    const row = (i + 1) * PAD + 1;
    const src = i * TILE;
    for (let j = 0; j < TILE; j++) E[row + j] = C[src + j];
  }
  // edges -- fall back to replicating the centre tile's own edge
  for (let k = 0; k < TILE; k++) {
    const top = get(1, TILE - 1, k);
    E[k + 1] = isNaN(top) ? C[k] : top;
    const bot = get(7, 0, k);
    E[(PAD - 1) * PAD + (k + 1)] = isNaN(bot) ? C[(TILE - 1) * TILE + k] : bot;
    const lef = get(3, k, TILE - 1);
    E[(k + 1) * PAD] = isNaN(lef) ? C[k * TILE] : lef;
    const rig = get(5, k, 0);
    E[(k + 1) * PAD + (PAD - 1)] = isNaN(rig) ? C[k * TILE + TILE - 1] : rig;
  }
  // corners
  E[0] = get(0, TILE - 1, TILE - 1);
  E[PAD - 1] = get(2, TILE - 1, 0);
  E[(PAD - 1) * PAD] = get(6, 0, TILE - 1);
  E[PAD * PAD - 1] = get(8, 0, 0);
  const corners = [0, PAD - 1, (PAD - 1) * PAD, PAD * PAD - 1];
  for (const idx of corners) if (isNaN(E[idx])) E[idx] = E[PAD + 1];
  return E;
}

// ---- shading ----------------------------------------------------------------

function mix(base: number, v: number, w: number): number {
  return base * (1 - w) + v * w;
}

/** Photoshop/QGIS "Overlay": base decides, top modulates. base 0..255, top 0..1, result 0..255. */
function overlay(base: number, top: number): number {
  const b = base / 255;
  return 255 * (b <= 0.5 ? 2 * b * top : 1 - 2 * (1 - b) * (1 - top));
}

/** "Hard light": the top decides. Shadows (top < 0.5) multiply, lit (top > 0.5) screen. */
function hardLight(base: number, top: number): number {
  const b = base / 255;
  return 255 * (top <= 0.5 ? 2 * b * top : 1 - 2 * (1 - b) * (1 - top));
}

function hsl2rgb(h: number, s: number, l: number): [number, number, number] {
  const f = (n: number): number => {
    const k = (n + h * 12) % 12;
    const A = s * Math.min(l, 1 - l);
    return 255 * (l - A * Math.max(-1, Math.min(Math.min(k - 3, 9 - k), 1)));
  };
  return [f(0), f(8), f(4)];
}

/** Ground resolution in metres/pixel at the centre latitude of tile row `y` at zoom `z`. */
export function groundResolution(z: number, y: number): number {
  // Web-mercator metres are not ground metres, and at 60N the difference is
  // a factor of two -- get it wrong and every slope angle is wrong.
  const n = Math.pow(2, z);
  const latRad = Math.atan(Math.sinh(Math.PI * (1 - (2 * (y + 0.5)) / n)));
  return (EARTH / (TILE * n)) * Math.cos(latRad);
}

/**
 * Shade one tile. `E` is the 258x258 padded elevation grid; the result is
 * 256x256 RGBA, alpha 0 where the centre tile has no data.
 */
export function shade(E: Float32Array, z: number, y: number, o: ShadeParams, ramps: Ramps): Uint8ClampedArray<ArrayBuffer> {
  const res = groundResolution(z, y);
  const out = new Uint8ClampedArray(TILE * TILE * 4);
  const azRad = ((360 - o.az + 90) * Math.PI) / 180; // math convention
  const zenRad = ((90 - o.alt) * Math.PI) / 180;
  const cosZen = Math.cos(zenRad);
  const sinZen = Math.sin(zenRad);
  const eightRes = 8 * res;
  const { slopeLut, bandLut, bandInterval } = ramps;

  for (let i = 0; i < TILE; i++) {
    for (let j = 0; j < TILE; j++) {
      const p = (i + 1) * PAD + (j + 1);
      const c = E[p];
      const q = (i * TILE + j) * 4;
      if (isNaN(c)) {
        out[q + 3] = 0;
        continue;
      }

      // Horn 3x3 gradient
      let a = E[p - PAD - 1];
      let b = E[p - PAD];
      let cc = E[p - PAD + 1];
      let d = E[p - 1];
      let f = E[p + 1];
      let g = E[p + PAD - 1];
      let h = E[p + PAD];
      let ii = E[p + PAD + 1];
      if (isNaN(a) || isNaN(b) || isNaN(cc) || isNaN(d) || isNaN(f) || isNaN(g) || isNaN(h) || isNaN(ii)) {
        a = b = cc = d = f = g = h = ii = c;
      }
      const dzdx = ((cc + 2 * f + ii - (a + 2 * d + g)) / eightRes) * o.ve;
      const dzdy = ((g + 2 * h + ii - (a + 2 * b + cc)) / eightRes) * o.ve;

      const slope = Math.atan(Math.sqrt(dzdx * dzdx + dzdy * dzdy));
      const slopeDeg = (slope * 180) / Math.PI;
      const aspect = Math.atan2(dzdy, -dzdx);

      // The stack, bottom to top: aspect tint, elevation banding, slope ramp,
      // hillshade. Each ramp's slider is its opacity over what is beneath, so
      // an opaque banding hides the aspect tint entirely.
      let r = 255;
      let gg = 255;
      let bb = 255;
      let under = false;

      // --- bottom: aspect tint (hue = direction, saturation grows with slope) --
      if (o.as > 0) {
        const deg = (((450 - (aspect * 180) / Math.PI) % 360) + 360) % 360;
        const sat = Math.min(1, slopeDeg / 15); // flats stay neutral
        const rgb = hsl2rgb(deg / 360, 0.65 * sat, 0.5);
        r = mix(r, rgb[0], o.as);
        gg = mix(gg, rgb[1], o.as);
        bb = mix(bb, rgb[2], o.as);
        under = true;
      }

      // --- cyclic elevation banding -------------------------------------------
      if (o.md > 0) {
        const m = c - Math.floor(c / bandInterval) * bandInterval; // wraps
        let mi = ((m / bandInterval) * (LUT_N - 1)) | 0;
        mi *= 3;
        r = mix(r, bandLut[mi], o.md);
        gg = mix(gg, bandLut[mi + 1], o.md);
        bb = mix(bb, bandLut[mi + 2], o.md);
        under = true;
      }

      // --- slope ramp over it ----------------------------------------------
      if (o.sl > 0) {
        let si = ((slopeDeg / 90) * (LUT_N - 1)) | 0;
        si = (si < 0 ? 0 : si > LUT_N - 1 ? LUT_N - 1 : si) * 3;
        r = mix(r, slopeLut[si], o.sl);
        gg = mix(gg, slopeLut[si + 1], o.sl);
        bb = mix(bb, slopeLut[si + 2], o.sl);
        under = true;
      }

      // --- hillshade on top ----------------------------------------------------
      if (o.hs > 0) {
        let hsv = cosZen * Math.cos(slope) + sinZen * Math.sin(slope) * Math.cos(azRad - aspect);
        hsv = hsv < 0 ? 0 : hsv > 1 ? 1 : hsv;
        if (!under || o.bl === 1) {
          // Plain transparency of the grey hillshade. Also the only choice with
          // nothing underneath: every blend mode is an identity on white.
          const v = 255 * hsv;
          r = mix(r, v, o.hs);
          gg = mix(gg, v, o.hs);
          bb = mix(bb, v, o.hs);
        } else if (o.bl === 3) {
          // Multiply, normalised so flat ground (hsv == cosZen) is untouched:
          // shadows darken the ramp, lit slopes leave it alone.
          const k = Math.min(1, hsv / cosZen);
          r = mix(r, r * k, o.hs);
          gg = mix(gg, gg * k, o.hs);
          bb = mix(bb, bb * k, o.hs);
        } else {
          // Overlay (base decides) or hard light (hillshade decides), with the
          // hillshade normalised so flat ground lands on the modes' neutral
          // 0.5. Raw hillshade values put flat ground at cos(zenith) -- 0.71
          // for a 45 degree sun -- which is above neutral, so every ramp
          // colour got lightened before any relief was added and the stack
          // read as washed out and transparent. Overlay is an identity on
          // pure white (the slope ramp's 10-32 degree band); hard light is
          // the choice when shade must show there too.
          const t = Math.min(1, (0.5 * hsv) / cosZen);
          const f = o.bl === 2 ? hardLight : overlay;
          r = mix(r, f(r, t), o.hs);
          gg = mix(gg, f(gg, t), o.hs);
          bb = mix(bb, f(bb, t), o.hs);
        }
      }

      out[q] = r;
      out[q + 1] = gg;
      out[q + 2] = bb;
      out[q + 3] = 255;
    }
  }
  return out;
}
